import { test, expect } from '@playwright/test';

test.describe('Accessibility - Form Fields Labels', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form'); // Replace with the actual URL of the form
  });

  test('should have associated labels for input fields', async ({ page }) => {
    const nameLabel = await page.getByLabel('Name');
    const emailLabel = await page.getByLabel('Email');

    expect(await nameLabel.isVisible()).toBe(true);
    expect(await emailLabel.isVisible()).toBe(true);
  });

  test('should read labels correctly with screen reader', async ({ page }) => {
    const nameInput = await page.getByRole('textbox', { name: 'Name' });
    const emailInput = await page.getByRole('textbox', { name: 'Email' });

    await nameInput.focus();
    await page.keyboard.press('Tab'); // Simulate screen reader navigation
    await emailInput.focus();

    const nameLabelText = await nameInput.evaluate(input => input.getAttribute('aria-label'));
    const emailLabelText = await emailInput.evaluate(input => input.getAttribute('aria-label'));

    expect(nameLabelText).toBe('Name');
    expect(emailLabelText).toBe('Email');
  });
});
